insert into public.page_sections (page_id, section_key, eyebrow, title, subtitle, body, cta_label, cta_url, image_media_id, video_url, sort_order, extra)
select id, 'legal', null, null, null, null, null, null, null, null, 1, '{"items":[{"title":"Who we are","body":"Not by Accident is an independent creative company. When we refer to “we”, “us” or “our” in this notice, we mean Not by Accident. When we refer to “you”, we mean anyone who visits this website or corresponds with us. Our full registered company details will be added here before this notice is treated as final.\n\nThis notice explains what we collect, why we collect it, and what you can ask us to do about it. It is written to be read, not to be survived."},{"title":"What we collect","body":"We collect only what a conversation requires. When you write to us through the contact form or by email, we hold your name, your company, your email address and whatever you choose to tell us about your project. We keep it for as long as the conversation is live and for a reasonable period afterwards.\n\nWhen you browse the site, our hosting provider records standard technical information: the pages requested, the approximate region, the browser used. This is ordinary server activity, not surveillance."},{"title":"Why we hold it","body":"We use your information for one purpose: to respond to you and, where it becomes relevant, to carry out work you have asked us to do. We do not sell it. We do not build advertising profiles. We do not enrich it with data bought from elsewhere.\n\nOur lawful basis is either your consent, given when you write to us, or our legitimate interest in running a small business well."},{"title":"Who sees it","body":"Your information is seen by the people at Not by Accident who need to see it, and by a short list of service providers who help us operate: email, hosting and analytics. Each is bound by its own obligations. We choose them carefully and review them."},{"title":"Your rights","body":"You may ask to see the information we hold about you, to correct it, or to have it deleted. You may withdraw consent at any time. You may also complain to the Information Commissioner’s Office, though we would rather you told us first, so we can put it right.\n\nTo exercise any of these rights, write to hello@notbyaccident.com. We will respond within one month, usually sooner."}]}'::jsonb
from public.pages where slug = 'next/privacy'
on conflict (page_id, section_key) do nothing;
